// Old pattern:
function OldQuestForm() {
  const [error, setError] = useState(null);
  const [success, setSuccess] = useState(false);
  const [isPending, setIsPending] = useState(false);

  async function handleSubmit(e) {
    e.preventDefault();
    setIsPending(true);
    try {
      await new Promise(r => setTimeout(r, 500)); // Mock API
      setSuccess(true);
    } catch (err) {
      setError(err.message);
    } finally {
      setIsPending(false);
    }
  }

  return (
    <form onSubmit={handleSubmit} data-testid="old-form">
      {error && <p role="alert">{error}</p>}
      {success && <p>Quest created!</p>}
      <button type="submit" disabled={isPending}>
        {isPending ? 'Creating...' : 'Create Quest'}
      </button>
    </form>
  );
}

// TODO 2: New form using useActionState
async function createQuestAction(prevState, formData) {
  await new Promise(r => setTimeout(r, 500));
  return { success: true, error: null };
}

function NewQuestForm() {
  const [state, dispatch, isPending] = useActionState(createQuestAction, { success: false, error: null });

  return (
    <form action={dispatch} data-testid="new-form">
      {state.error && <p role="alert">{state.error}</p>}
      {state.success && <p data-testid="success">Quest created!</p>}
      <button type="submit" disabled={isPending} data-testid="submit-btn">
        {isPending ? 'Creating...' : 'Create Quest'}
      </button>
    </form>
  );
}

export default function App() {
  return (
    <div data-testid="app">
      <NewQuestForm />
    </div>
  );
}
